#include <iostream>
#include <array>

int main() {
    std::array<int, 5> items = {1, 2, 3, 4, 5};

    // Display items before modification using pass-by-value
    std::cout << "items before modification: ";
    for (int item : items) {
        std::cout << item << " ";
    }
    std::cout << "\n";

    // Multiply elements by 2 using pass-by-reference
    for (int &itemRef : items) {
        itemRef *= 2;
    }

    // Display items after modification
    std::cout << "items after modification: ";
    for (int item : items) {
        std::cout << item << " ";
    }
    std::cout << std::endl;

    return 0;
}

